+        }
+
+        public long getCount() {
+            return count;
+        }
+
+        public long getSkippedCount() {
+            return skippedCount;
+        }
+
+        public LongMetricValue getTook() {
+            return took;
+        }
+
+        @Override
+        public boolean equals(Object o) {
